CREATE TABLE project_technical_plans (project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version INTEGER NOT NULL DEFAULT 0, mutation_token TEXT, updated_at TEXT NOT NULL);
CREATE TABLE project_technical_plan_nodes (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, node_id TEXT NOT NULL, parent_node_id TEXT, sort_order INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', content_mode TEXT NOT NULL DEFAULT 'manual-fill', content_mode_note TEXT, source_requirement_id TEXT, source_requirement_title TEXT, knowledge_item_ids_json TEXT, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'idle', plan_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(project_id, node_id), FOREIGN KEY(project_id, parent_node_id) REFERENCES project_technical_plan_nodes(project_id, node_id) ON DELETE CASCADE);
CREATE INDEX project_technical_plan_parent ON project_technical_plan_nodes(project_id, parent_node_id, sort_order);
